import { type ReactNode, useEffect } from "react";

import { Button } from "@/components/ui/button";

// PROTOTYPE: Three variants of the outside-store-hours warning, switchable via
// `?hoursVariant=`, on the existing Capture route.
export const HOURS_VARIANTS = ["a", "b", "c"] as const;

export type HoursVariant = (typeof HOURS_VARIANTS)[number];

const VARIANT_NAMES: Record<HoursVariant, string> = {
  a: "Left rail",
  b: "Soft banner",
  c: "Hours comparison",
};

export function OutsideStoreHoursPrototype({
  variant,
}: Readonly<{ variant: HoursVariant }>): ReactNode {
  if (variant === "b") {
    return (
      <div
        className="grid gap-2 rounded-lg border border-warning/70 bg-warning/15 p-3"
        id="store-hours-warning"
      >
        <div className="flex items-center gap-2 font-semibold text-sm">
          <AlertTriangle
            aria-hidden="true"
            className="size-5 text-warning-foreground"
          />
          <span>Outside store hours</span>
        </div>
        <p className="text-muted-foreground text-xs">
          Label times are usually between 9:00 AM and 8:00 PM. Check the printed
          label before saving.
        </p>
      </div>
    );
  }

  if (variant === "c") {
    return (
      <div
        className="grid grid-cols-[auto_1fr] items-center gap-x-3 rounded-lg bg-warning/15 p-3"
        id="store-hours-warning"
      >
        <span className="row-span-2 grid size-9 place-items-center rounded-full bg-warning text-warning-foreground">
          <ClockAlert aria-hidden="true" className="size-5" />
        </span>
        <div className="flex items-baseline justify-between gap-3">
          <p className="font-semibold text-sm">Entered time</p>
          <p className="font-semibold text-sm text-warning-foreground">
            Outside hours
          </p>
        </div>
        <div className="flex items-baseline justify-between gap-3 border-warning/40 border-t pt-1">
          <p className="text-muted-foreground text-xs">Usual label times</p>
          <p className="text-xs">9:00 AM–8:00 PM</p>
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex items-start gap-3 bg-warning/15 px-3 py-2"
      id="store-hours-warning"
    >
      <AlertTriangle
        aria-hidden="true"
        className="mt-0.5 size-5 shrink-0 text-warning-foreground"
      />
      <div>
        <p className="font-semibold text-sm">Outside store hours</p>
        <p className="text-muted-foreground text-xs">
          Check that the label time is correct.
        </p>
      </div>
    </div>
  );
}

export function HoursPrototypeSwitcher({
  current,
  onChange,
}: Readonly<{
  current: HoursVariant;
  onChange: (variant: HoursVariant) => void;
}>): ReactNode {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent): void => {
      const target = event.target;
      if (
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        (target instanceof HTMLElement && target.isContentEditable)
      ) {
        return;
      }

      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") {
        return;
      }

      const currentIndex = HOURS_VARIANTS.indexOf(current);
      const offset = event.key === "ArrowLeft" ? -1 : 1;
      const nextIndex =
        (currentIndex + offset + HOURS_VARIANTS.length) % HOURS_VARIANTS.length;
      onChange(HOURS_VARIANTS[nextIndex]);
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [current, onChange]);

  const cycle = (offset: -1 | 1): void => {
    const currentIndex = HOURS_VARIANTS.indexOf(current);
    const nextIndex =
      (currentIndex + offset + HOURS_VARIANTS.length) % HOURS_VARIANTS.length;
    onChange(HOURS_VARIANTS[nextIndex]);
  };

  return (
    <div className="fixed bottom-20 left-1/2 z-50 flex -translate-x-1/2 items-center gap-2 rounded-full bg-foreground p-1.5 text-background shadow-xl">
      <Button
        aria-label="Previous warning variant"
        onClick={() => cycle(-1)}
        size="icon-sm"
        type="button"
        variant="secondary"
      >
        <ChevronLeft aria-hidden="true" />
      </Button>
      <output className="min-w-36 text-center font-medium text-xs">
        {current.toUpperCase()} — {VARIANT_NAMES[current]}
      </output>
      <Button
        aria-label="Next warning variant"
        onClick={() => cycle(1)}
        size="icon-sm"
        type="button"
        variant="secondary"
      >
        <ChevronRight aria-hidden="true" />
      </Button>
    </div>
  );
}

